package vn.io.oldmoon.shopizer.common.core.utility;

import java.util.UUID;

/**
 * Utility class for generating and normalizing URL-friendly slugs.
 */
public final class SlugUtil {

  private SlugUtil() {}

  /**
   * Generates or normalizes a slug based on an optional explicit slug and a fallback name.
   * If the explicit slug is provided and not blank, it is trimmed and converted to lower case.
   * If the explicit slug is null or blank, and the fallback name is provided and not blank,
   * a slug is generated by converting the name to lower case, replacing whitespace sequences
   * with hyphens, and appending an 8-character unique UUID suffix.
   * If neither is provided, returns the original slug.
   *
   * @param slug the explicit slug (may be null or blank)
   * @param name the fallback name or title (may be null or blank)
   * @return the normalized slug, auto-generated slug, or original slug value
   */
  public static String generateSlug(String slug, String name) {
    if (slug != null && !slug.isBlank()) {
      return slug.trim().toLowerCase();
    }

    if (name != null && !name.isBlank()) {
      String base = name.trim().toLowerCase().replaceAll("\\s+", "-");
      String uniqueCode = UUID.randomUUID().toString().substring(0, 8);
      return base + "-" + uniqueCode;
    }

    return slug;
  }

}
